<?php
$totals=['employees'=>0,'gross'=>0,'deductions'=>0,'net'=>0,'exceptions'=>0,'published'=>0];foreach($runs as $r)foreach($totals as $key=>$v)$totals[$key]+=(int)$r[$key];
$q=$pdo->prepare('SELECT e.snapshot,e.exceptions FROM hr_payroll_entries e JOIN hr_payroll_runs r ON r.id=e.run_id WHERE r.month=?');$q->execute([$month]);$missing=0;$attendanceIssues=0;$unpaid=0;$generated=0;
foreach($q as $entry){$s=json_decode($entry['snapshot'],true)?:[];if(str_contains($entry['exceptions'],'Missing Salary'))$missing++;elseif($entry['exceptions']!=='')$attendanceIssues++;if(($s['attendance']['unpaid_leave']??0)>0)$unpaid++;if(!empty($s['draft_generated_at']))$generated++;}
?>
<section class="pay-kpis" aria-label="Payroll summary"><?php foreach(['Employees'=>['employees',false],'Monthly gross payroll'=>['gross',true],'Salary deductions'=>['deductions',true],'Net payroll'=>['net',true],'Published payslips'=>['published',false],'Action required'=>['exceptions',false]] as $label=>[$key,$money]):?><article class="card pay-kpi"><span class="pay-kpi-label"><?=h($label)?></span><strong><?=$money?pay_amount($totals[$key]):$totals[$key]?></strong></article><?php endforeach;?></section>
<section class="card pay-card"><h2><?=h(date('F Y',strtotime($month.'-01')))?> payroll</h2><p>Employee salary → final attendance → deductions → monthly payroll → payslip.</p><div class="pay-grid"><div><strong>Attendance review</strong><p><?=$totals['employees']?($totals['exceptions']?'Action required':'No recorded payroll exceptions'):'Not calculated'?></p></div><div><strong>Payroll calculation</strong><p><?=h($runs[0]['status']??'Not started')?></p></div><div><strong>Payslips</strong><p><?=$totals['published']?> published · <?=$generated?> draft copies prepared</p></div></div><a class="button primary" href="?page=payroll_processing&amp;month=<?=h($month)?>">Open Monthly Payroll</a></section>
<section class="card pay-card"><h2>Review before finalizing</h2><div class="pay-grid"><p>Missing salary <strong><?=$missing?></strong></p><p>Attendance / calculation issues <strong><?=$attendanceIssues?></strong></p><p>Employees with unpaid leave <strong><?=$unpaid?></strong></p></div><p class="pay-muted">Counts reflect the selected payroll snapshot. Recalculate draft payroll after correcting attendance or salary. Published months retain their saved values.</p></section>
